    ("0ce8854d-ed6c-45d6-ac84-8b5e44b44f32", "судомитися; трястися або смикатися неконтрольовано", "Від сміху вона буквально судомилася."),
    ("582e57e1-0244-4251-b4b0-9eacc9b13f65", "підтверджувати; підкріплювати твердження доказами", "Свідок підтвердив показання підозрюваного."),
    ("6786e919-5c01-40bd-b436-1fc45eff67ec", "кліка; невелика замкнена група людей зі спільними інтересами", "Вона стала частиною елітного кола митців."),
    ("ad51d01f-607a-4050-aba1-7c22d0f07319", "обличчя; вираз або вигляд обличчя людини", "На її обличчі читалося глибоке задоволення."),
    ("de52ec23-5367-457d-959f-765a820fd0aa", "тулитися; присідати від страху", "Маленький собака тулився в кутку під час грози."),
    ("ca000003-0000-4000-8000-000000001003", "пригнічений; сумний і розчарований після невдачі", "Програвши фінал, команда виглядала пригніченою."),
    ("c700002e-0000-4000-8000-00000000072e", "досягати кульмінації; досягати найвищої точки", "Роки навчання завершилися отриманням диплому."),
    ("bf030ed6-9989-43bd-850d-b220bcfb6d30", "уривчастий; коротко і різко відповідати", "Його уривчаста відповідь дала зрозуміти небажання говорити."),
    ("c700001b-0000-4000-8000-00000000071b", "охоронець; людина, відповідальна за щось", "Директор музею виступав охоронцем національних цінностей."),
    ("8a23bbf1-1e38-4f83-8249-871672393acf", "охайний; акуратний і добре вдягнений", "Охайний джентльмен у костюмі привернув увагу всіх."),
    ("31514bb7-814c-410a-8d39-ac387a2f9470", "нестача; брак або дефіцит чогось", "Відчувалася гостра нестача кваліфікованих спеціалістів."),
    ("58f71b4b-9525-4af9-8e4f-2750a68433d2", "елегантний; впевнений, стильний і чарівний", "Елегантний актор підкорив серця глядачок."),
    ("ddf47036-ad66-4662-861d-0ff50365ef00", "декадентський; розкішно-потурального характеру", "Декадентський десерт із шоколаду був нестримно смачним."),
    ("ca000013-0000-4000-8000-000000001013", "рішучий; здатний швидко і впевнено приймати рішення", "Рішучий менеджер миттєво відреагував на кризу."),
    ("cb000006-0000-4000-8000-000000001106", "пригнічений; сумний і пригнічений духом", "Після поразки він виглядав глибоко пригніченим."),
    ("ca00002b-0000-4000-8000-00000000102b", "смачний; надзвичайно приємний на смак", "Смачний пиріг зникав зі столу миттєво."),
    ("ca000017-0000-4000-8000-000000001017", "делегат; особа, уповноважена представляти інших", "Вона була делегатом від свого регіону на конференції."),
    ("0b3146a1-4323-4d33-9a23-0e9f63c57718", "маячня; хибне переконання, що зберігається всупереч доказам", "Його маячня про переслідування турбувала рідних."),
    ("ad5fdacd-515e-4d3c-83bf-d56c123f4c14", "поведінка; зовнішній вигляд і манера поведінки", "Її спокійна поведінка заспокоювала оточуючих."),
    ("cb000014-0000-4000-8000-000000001114", "скромний; стриманий і сором'язливий", "Скромна дівчина говорила тихо і уважно слухала."),
    ("cb000008-0000-4000-8000-000000001108", "заперечення; відмова визнати правду або реальність", "Його заперечення провини виглядало непереконливо."),
    ("fec7aa77-13b2-4b52-bab0-19b68775cd9d", "принижувати; несправедливо критикувати або зневажати", "Ніхто не має права принижувати інших за переконання."),
    ("b5000022-0000-4000-8000-000000000522", "розв'язка; кінцева розв'язка сюжету твору", "Несподівана розв'язка детективу вразила читачів."),
    ("cb000022-0000-4000-8000-000000001122", "засуджувати; публічно засуджувати когось або щось", "Він рішуче засудив корупцію у своїй промові."),
    ("b5000005-0000-4000-8000-000000000505", "розгортання; введення програмного забезпечення у роботу", "Розгортання нової версії системи пройшло успішно."),
    ("ad67620a-4086-42f5-a70c-99a31d639d9f", "заступник; особа, призначена діяти замість іншої", "Заступник мера взяв на себе обов'язки під час відпустки."),
    ("ade239b2-5971-445d-aebc-f56919f955a0", "висміювати; виражати презирство шляхом глузування", "Не варто висміювати чужі мрії."),
    ("5807f2a9-5869-4162-acf4-6601b164be4c", "відчай; стан пригніченості від втрати надії", "Після серії невдач його охопив глибокий відчай."),
    ("7024c6b0-8d48-49ab-8328-71143b9ef48c", "відчайдушний; пригнічений від втрати надії", "Відчайдушний студент не міг змусити себе вчитися."),
    ("989bcc74-cfd9-40f5-9969-cfa22487e8ab", "деспот; правитель з необмеженою владою, часто жорстокий", "Народ повстав проти жорстокого деспота."),
    ("29cacfad-4265-419c-b494-af4bdcc63db3", "хитрий; той, хто досягає мети нечесними засобами", "Хитрий адвокат знайшов лазівку в законі."),
    ("cb00002c-0000-4000-8000-00000000112c", "поглинати; їсти жадібно і швидко", "Голодна дитина поглинула суп за кілька секунд."),
    ("c7000026-0000-4000-8000-000000000726", "спритність; майстерність, особливо в ручній роботі", "Хірург проявив неабияку спритність рук."),
    ("de271734-bf61-4fc5-8299-bad60aa1d336", "дихотомія; поділ між різко контрастними речами", "Між теорією і практикою існує очевидна дихотомія."),
    ("ad610671-36ea-4beb-8f84-90cb876f493f", "вислів; офіційний або авторитетний вирок", "Цей юридичний вислів став основою нових законів."),
    ("5a292e9b-48ce-48e2-94ce-76f9a3fff256", "невпевнений; скромний через брак самовпевненості", "Невпевнений студент соромився відповідати на уроці."),
    ("3a569592-6658-4cda-8874-79a0ecff644a", "сановник; особа, що обіймає високу посаду", "На урочистостях були присутні численні сановники."),
    ("c7000020-0000-4000-8000-000000000720", "відхилятися; відступати від головної теми", "Він часто відхилявся від теми під час лекцій."),
    ("3900e6f2-ff23-440d-b42d-1a9bfa415f99", "розрізняти; розпізнавати з зусиллям", "Важко було розрізнити справжній твір від підробки."),
    ("dbfe3876-5bc8-4909-beac-6dc8442dc830", "учень; послідовник учителя або лідера", "Молодий учень повністю присвятив себе вивченню мистецтва."),
    ("9ecfe303-ce9a-4714-b92a-c7be9498b05c", "розбіжність; невідповідність між двома речами", "Бухгалтер виявив розбіжність у фінансових звітах."),
    ("9c27d96c-98f2-4b4b-b3dc-a19e70c3913d", "розсудливість; обережність і тактовність у діях", "Він проявив розсудливість, не розповідаючи зайвого."),
    ("58cd1dab-324d-44a7-89c2-bd17e158d870", "розпатланий; неохайний, з безладним волоссям", "Після прогулянки під дощем вона виглядала розпатланою."),
    ("e2cabd9d-c97a-4cb4-80e1-d96145b6e145", "розчарування; відчуття від виявленої гіршої реальності", "Розчарування від першої роботи було сильним."),
    ("7960f4ea-1280-43b5-8b23-ed376892ffb4", "применшувати; зневажливо відгукуватися про когось", "Він завжди намагався применшити заслуги колег."),
    ("c700000b-0000-4000-8000-00000000070b", "характер; природжені якості розуму і поведінки", "За характером вона була оптимісткою."),
    ("b500002d-0000-4000-8000-00000000052d", "незгода; розбіжність з офіційною думкою", "Науковець відкрито висловив незгоду з панівною теорією."),
    ("01080b44-7326-4838-8243-698ef8948094", "дисидент; особа, яка відкрито виступає проти офіційної політики", "Дисидент провів роки у вигнанні за свої переконання."),
    ("59bc15ba-7b72-41af-bb0a-08efa16278b8", "дисонанс; відсутність гармонії або злагодженості", "Когнітивний дисонанс виник, коли факти суперечили переконанням."),
    ("8b12c975-04f2-488c-a5e1-95f8d1521fbc", "розголошувати; розкривати раніше таємну інформацію", "Він відмовився розголошувати конфіденційні дані."),
    ("b5000029-0000-4000-8000-000000000529", "доктрина; система переконань, якої дотримується група", "Стратегічна доктрина компанії зазнала змін."),
    ("52cfb3b3-17fe-45c2-be24-c7ae09f22bd0", "владний; нав'язливо стверджує свою волю над іншими", "Владний керівник не давав іншим висловитися."),
    ("863d8cbe-d4f6-43b8-857f-6c45ede34fdd", "жах; сильний страх перед чимось майбутнім", "Думка про публічний виступ викликала у неї жах."),
    ("8c72622f-f251-4fb1-bb4b-e6f1fff84bdb", "кумедний; розважальний у дивакуватий спосіб", "Його кумедні коментарі завжди піднімали настрій."),
    ("5b7e38c5-8251-42ec-8b90-a9ef524ee086", "дволикий; нещирий, що говорить і діє суперечливо", "Дволикий чиновник приховував свої справжні наміри."),
    ("c700002f-0000-4000-8000-00000000072f", "зменшуватися; поступово скорочуватися", "Запаси їжі швидко зменшувалися."),
    ("a9dc2cd9-1329-4d66-a02f-c19d54627346", "захоплений; нестримно виражає подяку або схвалення", "Вона була захоплено вдячна за надану допомогу."),
    ("b500002f-0000-4000-8000-00000000052f", "егалітарний; що вірить у рівні права та можливості для всіх", "Егалітарний підхід забезпечував рівні можливості всім."),
    ("6e1f7838-89ff-411f-8f6a-cdbe598445ff", "розробляти; додавати більше деталей до сказаного", "Він попросив її докладніше розповісти про план."),
    ("c7000002-0000-4000-8000-000000000702", "ейфорія; велике щастя і збудження", "Ейфорія від перемоги переповнювала серця уболівальників."),
    ("177e4478-98cd-4a0b-99be-be2a078b2546", "прояснювати; пояснювати детально", "Професор прояснив складну концепцію простими прикладами."),
    ("c700001c-0000-4000-8000-00000000071c", "посланець; людина, що виконує особливу дипломатичну місію", "Уряд відправив посланця на переговори."),
    ("5b1b3328-6d1e-46b3-ba13-972df6ee9733", "почет; група помічників, що супроводжують важливу особу", "Зірка прибула з великим почтом."),
    ("b500000f-0000-4000-8000-00000000050f", "ентропія; міра безладу; тенденція систем до хаосу", "Без підтримки ентропія системи швидко зростала."),
    ("cb00001e-0000-4000-8000-00000000111e", "чітко вимовляти; виразно промовляти слова", "Диктор чітко вимовляв кожне слово."),
    ("90ca60e4-36f1-4f50-b1e1-8866b5e8e855", "посланник; представник, особливо дипломатичний", "Спеціальний посланник прибув для врегулювання конфлікту."),
    ("b5000014-0000-4000-8000-000000000514", "фермент; білок, що прискорює хімічні реакції", "Травні ферменти допомагають розщеплювати їжу."),
    ("c30122c1-a0ac-4d9d-a914-5b771ba03045", "епіграма; дотепне й лаконічне висловлювання", "Його епіграма точно описувала суть ситуації."),
    ("397c035c-e443-4b8e-ae83-791fe7a008e2", "втілення; ідеальний приклад певної якості", "Вона є втіленням елегантності та вишуканості."),
    ("8a0a2dda-d219-4b43-b758-d6958c72bfd3", "душевна рівновага; спокій і витримка за умов стресу", "Він зберігав душевну рівновагу попри всі труднощі."),
    ("b5000010-0000-4000-8000-000000000510", "рівновага; стан балансу між протилежними силами", "Після кризи ринок знову досяг рівноваги."),
    ("cb00002e-0000-4000-8000-00000000112e", "загострюватися; стрімко зростати за інтенсивністю", "Конфлікт між сусідами почав загострюватися."),
    ("0051beb9-3615-484c-be6f-17cb6350a1e0", "ейфорія; відчуття сильного збудження і щастя", "Перемога викликала хвилю ейфорії серед уболівальників."),
    ("855c2a2e-05cf-44f5-aacc-bd18fb197e12", "ейфоричний; що відчуває сильне щастя або піднесення", "Ейфоричні фани святкували на вулицях."),
    ("c7000005-0000-4000-8000-000000000705", "роздратування; почуття сильного роздратування", "З роздратуванням вона поклала трубку."),
    ("33cba38a-a2b9-48ad-bac5-43e0bd21af13", "піднесення; відчуття живого, веселого збудження", "Стрибок із парашутом наповнив його неймовірним піднесенням."),
    ("6914e589-caf0-4c43-86ac-9c5921a08e38", "викладати; детально пояснювати щось", "Він цілу годину викладав свою теорію перед колегами."),
    ("e95d2b54-489d-4d0b-a2a5-0cf2fa6e114b", "прославляти; захоплено хвалити", "Критики прославляли дебютний роман письменника."),
    ("8e53a19e-a9aa-4443-bbe4-edc7e6b2b742", "вибагливий; той, хто звертає велику увагу на деталі", "Вибагливий редактор виловлював навіть найменші помилки."),
    ("8707bd09-d9b5-44b2-a476-43e5c1a27c41", "збагнути; глибоко зрозуміти після роздумів", "Важко збагнути, чому він прийняв таке рішення."),
    ("ca000031-0000-4000-8000-000000001031", "здійсненний; можливий для зручного виконання", "Команда перевірила, чи здійсненний запропонований план."),
    ("c700002b-0000-4000-8000-00000000072b", "бродити; зазнавати хімічної зміни від мікроорганізмів", "Виноград бродить у бочках кілька тижнів."),
    ("6130595c-649b-4355-a8ee-ed51cf7dd7ff", "мінливий; той, хто часто змінює уподобання", "Мінлива погода в горах застала туристів зненацька."),
    ("cb00001b-0000-4000-8000-00000000111b", "номінальний керівник; лідер без реальної влади", "Президент виконував роль номінального керівника."),
    ("bf2c07d9-fbc0-4a3a-9449-9889bd752ed0", "розмахувати; дико розмахувати руками або ногами", "Він розмахував руками, намагаючись утримати рівновагу."),
    ("ca000024-0000-4000-8000-000000001024", "здригатися; мимоволі смикатися від страху або болю", "Вона навіть не здригнулася, коли лікар зробив укол."),
    ("cb000017-0000-4000-8000-000000001117", "несерйозний; що не виявляє поваги", "Несерйозна відповідь на серйозне запитання образила всіх."),
    ("0cbe8e76-a0ae-4fab-82ae-aa3767886404", "предок; особа, від якої хтось походить", "Її предки прийшли з Галичини ще у XIX столітті."),
    ("c7000006-0000-4000-8000-000000000706", "передчуття лиха; відчуття, що станеться щось погане", "Важке передчуття не покидало його весь день."),
    ("c9c9fa64-8f98-4699-ae72-5e3157d0bccc", "передбачення; здатність передбачати майбутні потреби", "Завдяки передбаченню директора компанія уникла кризи."),
    ("ca000005-0000-4000-8000-000000001005", "покинутий; жалісно сумний і самотній", "Покинуте кошеня сиділо під дощем і нявкало."),
    ("754bcde1-dfb4-4909-b994-e67c6e20c9bf", "мужність; хоробрість і сила у боротьбі з труднощами", "Він переніс хворобу з неймовірною мужністю."),
    ("cb000032-0000-4000-8000-000000001132", "виховувати; сприяти розвитку; доглядати нерідну дитину", "Школа намагалася виховувати в учнях любов до читання."),
    ("c7000012-0000-4000-8000-000000000712", "ощадливий; обережний у витраті грошей", "Ощадливий господар нічого не витрачав даремно."),
    ("93d85aa1-6ef0-46ba-8b32-b978aacfa8b3", "хода; манера ходи людини", "По ході можна впізнати знайому людину здалеку."),
    ("c700002c-0000-4000-8000-00000000072c", "прикрашати; прикрашати страву невеликими додатками", "Шеф-кухар прикрасив страву свіжою зеленню."),
    ("6a339a86-d8f9-4072-a56c-fff7a4f0d863", "балакучий; надмірно говіркий, особливо про дрібниці", "Балакуча сусідка розповідала всі сільські новини."),
    ("cb00000f-0000-4000-8000-00000000110f", "привітний; дружній і веселий у поводженні", "Привітний хазяїн зустрів гостей із посмішкою."),
    ("b5000017-0000-4000-8000-000000000517", "геном; повний набір генетичного матеріалу організму", "Розшифрування геному людини відкрило нові горизонти в медицині."),
    ("05628d15-3885-47f7-95c1-1ec80e055a30", "вишуканий; ввічливий і вихований, часто надмірно", "Родина жила бідно, але зберігала вишукані манери."),
    ("170300a1-929f-4ac1-a5a0-99eb577f4acd", "поверхневий; плавний, але нещирий у мовленні", "Його поверхневі відповіді не задовольнили журналістів."),
    ("573c9fc3-66f9-44bc-9a97-36bcc38c6406", "похмурий; засмучений і пригнічений", "Він сидів у кутку з похмурим виглядом."),
    ("4417e1a1-b175-42af-b577-9bddeac899a0", "чемний; ввічливий, добрий і приємний", "Господиня чемно зустріла всіх гостей."),
    ("f4d641ea-bdd3-434b-adf8-254d61b84d29", "боротися; схопитися і змагатися в сутичці", "Він довго боровся з важкою математичною задачею."),
    ("a971d420-92c2-4bdc-bf44-2f259b9f590a", "поважність; гідність і серйозність манери", "Його поважність і впевненість вразили аудиторію."),
    ("0f28a59f-0215-4bbb-a0c8-9ffd42a0c3d5", "тяжіти; природно тягнутися до когось або чогось", "Вона завжди тяжіла до творчих людей."),
    ("766f56e9-0131-4d24-8259-d60aaa2c576c", "товариський; що любить бути серед людей", "Товариський студент швидко познайомився з усім гуртожитком."),
    ("ca000025-0000-4000-8000-000000001025", "гримаса; викривлений вираз обличчя від болю або огиди", "Від гіркого ліку вона скривила гримасу."),
    ("badd40e4-5aea-40dc-8234-eba96fc22508", "плазувати; принижено вибачатися заради прощення", "Він відмовився плазувати перед начальником."),
    ("0c5964da-f1c7-4bc0-978d-33c04dc770cc", "брутальний; різкий і грубуватий у поводженні", "Брутальний голос охоронця злякав відвідувачів."),
    ("ca000012-0000-4000-8000-000000001012", "довірливий; той, кого легко обдурити", "Довірлива людина легко стає жертвою шахраїв."),
    ("cb000013-0000-4000-8000-000000001113", "пихатий; зарозуміло-зверхній і зневажливий", "Пихата манера поведінки відштовхувала людей від неї."),
    ("bb7adc84-5a83-40de-9793-98f2bbdd467f", "впертий; рішуче діє на власний розсуд попри поради", "Впертий юнак зробив усе по-своєму."),
    ("2425264f-6a55-4fae-8dc3-cf51d33ee35a", "підручний; відданий виконавець наказів, часто неетичних", "Бандит і його підручні пограбували банк."),
    ("b5000009-0000-4000-8000-000000000509", "евристика; практичне правило для швидкого вирішення завдань", "Евристика допомагає приймати рішення в умовах невизначеності."),
    ("cb000031-0000-4000-8000-000000001131", "заважати; ускладнювати щось", "Дощ заважав проведенню зовнішніх робіт."),
    ("b500001e-0000-4000-8000-00000000051e", "гіпербола; навмисне перебільшення для ефекту", "«Я чекав цілу вічність» — це гіпербола."),
    ("e43d879f-8f3b-4728-af18-01ce34dc8529", "лицемір; людина, яка вдає чесноти, яких не має", "Лицемір голосував за закон, якого сам не дотримувався."),
    ("b500002e-0000-4000-8000-00000000052e", "ідеологія; система ідей, що є основою переконань або політики", "Ідеологія партії ґрунтувалася на рівності та справедливості."),
    ("ef9b10df-55a3-4266-81d7-81c927ce6039", "незворушний; що не виражає емоцій", "Незворушний суддя слухав аргументи обох сторін."),
    ("91559213-0900-4f77-820c-d3054fa44d7b", "владний; зарозуміло домінуючий у манері", "Владний тон начальника не залишав місця для дискусії."),
    ("6d4a863b-ad87-406a-a32d-3179b65c6029", "запальний; що діє швидко і необдумано", "Запальний вчинок коштував йому дружби."),
    ("ca000022-0000-4000-8000-000000001022", "благати; щиро і наполегливо просити", "Вона благала його залишитися."),
    ("ca00000e-0000-4000-8000-00000000100e", "імпульсивний; той, хто діє раптово без обдумування", "Імпульсивне рішення виявилося помилковим."),
    ("2c2eb617-84f6-46a8-94e2-712d58363339", "той, хто обіймає посаду; нинішній власник посади", "Чинний мер балотувався на другий термін."),
    ("7e916c0c-d4c9-42c0-823c-dea00eb5c727", "обурений; розлючений через несправедливість", "Він був обурений несправедливим вироком."),
    ("ca868398-6184-4e8c-822e-354ceea601fe", "обурення; гнів від несправедливого поводження", "Рішення суду викликало загальне обурення."),
    ("c7000011-0000-4000-8000-000000000711", "лінивий; той, хто уникає зусиль та активності", "Лінивий студент відкладав усе на потім."),
    ("ca000014-0000-4000-8000-000000001014", "працьовитий; наполегливий і старанний", "Працьовита бджола стала символом наполегливості."),
    ("075e1a92-ff57-4a67-9a54-6be08e4277ed", "захопленість; сильна але короткочасна пристрасть", "Його захопленість кіноактрисою минула через місяць."),
    ("c700000c-0000-4000-8000-00000000070c", "гальмування; відчуття, що робить людину скутою", "Після кількох репетицій її гальмування зникли."),
    ("c700001f-0000-4000-8000-00000000071f", "натякати; непрямо вказувати на щось неприємне", "Він натякав, що колега присвоює чужі ідеї."),
    ("17ae7956-66be-45c8-ae40-ac5fa8e511e9", "прісний; без смаку або інтересу", "Прісна лекція наганяла нудьгу на студентів."),
    ("ca000021-0000-4000-8000-000000001021", "вставляти; раптово перебивати розмову", "Вона не могла втриматися і вставила своє зауваження."),
    ("b500000e-0000-4000-8000-00000000050e", "сумісний; здатний працювати з іншими системами", "Новий формат є сумісним з більшістю платформ."),
    ("907f91e8-92e5-4668-9832-0c47520d1cb8", "непоступливий; не готовий змінювати погляди", "Непоступлива позиція перешкоджала переговорам."),
    ("d5b8a6d3-0cd2-4544-9bd4-fa36789dd679", "безстрашний; хоробрий і підприємливий", "Безстрашний репортер поїхав у зону конфлікту."),
    ("ca000030-0000-4000-8000-000000001030", "складний; дуже деталізований і заплутаний", "Складний механізм годинника складається з сотень деталей."),
    ("8f633f89-742e-4783-aa8d-242c1b940bbb", "інтроспекція; дослідження власних думок і почуттів", "Тривала інтроспекція допомогла їй зрозуміти себе."),
    ("cb000003-0000-4000-8000-000000001103", "розлючений; надзвичайно сердитий", "Розлючений клієнт вимагав повернення грошей."),
    ("b5000013-0000-4000-8000-000000000513", "ізотоп; форма елемента з різною кількістю нейтронів", "Радіоактивний ізотоп вуглецю використовується для датування."),
    ("ca00b5eb-a8bc-456b-b03c-67aeb0c059f2", "жвавий; з живою, веселою і впевненою манерою", "Він йшов жвавим кроком, насвистуючи мелодію."),
    ("13fed87a-40ad-44d0-88cd-aa447b5e5cb5", "жартівливий; схильний до жартів і гумору", "Жартівливий тон промови зробив захід невимушеним."),
    ("cb000005-0000-4000-8000-000000001105", "веселий; бадьорий і дружній", "Веселий дідусь завжди мав у запасі цікаву історію."),
    ("cb000001-0000-4000-8000-000000001101", "тріумфуючий; що відчуває велике щастя після успіху", "Тріумфуюча команда святкувала перемогу."),
    ("08d48203-e414-4923-85e7-7071322d7ff0", "тріумф; відчуття великого щастя і перемоги", "Залу наповнила буря тріумфу після оголошення результатів."),
    ("b5000028-0000-4000-8000-000000000528", "юрисдикція; офіційна влада приймати правові рішення", "Справа потрапила під юрисдикцію міжнародного суду."),
    ("b500001d-0000-4000-8000-00000000051d", "зіставлення; розміщення двох речей поряд для контрасту", "Зіставлення старого і нового районів міста було разючим."),
    ("cb00001d-0000-4000-8000-00000000111d", "родичі; сімʼя і родичі", "Після переїзду вона сумувала за ріднею."),
    ("cb00002b-0000-4000-8000-00000000112b", "місити; місити тісто або глину руками", "Бабуся місила тісто для пирогів зранку."),
    ("ad1f9d50-efe7-48aa-9894-c99228e73552", "лаконічний; той, хто використовує мало слів", "Його лаконічна відповідь сказала більше за довгу промову."),
    ("c7000022-0000-4000-8000-000000000722", "сумувати; висловлювати скорботу або жаль", "Вона сумувала за минулими часами."),
    ("c973eed9-dca4-4cdb-854c-cc96172720b7", "худорлявий; незграбно довгий і тонкий", "Довготелесий підліток дріботів через зал."),
    ("431df84f-db01-4469-96a8-041e7bf4ee5f", "млявість; стан фізичної або психічної стомленості", "Після хвороби її тривалий час мучила млявість."),
    ("c7000025-0000-4000-8000-000000000725", "млявість; брак енергії та ентузіазму", "Зимова млявість не давала йому братися за нові проекти."),
    ("cb000018-0000-4000-8000-000000001118", "зв'язок; посередник між групами", "Вона виступала зв'язком між відділами компанії."),
    ("ed136693-6809-4854-a8b5-6ad54c772fb2", "гнучкий; тонкий, гнучкий і граціозний у рухах", "Гнучка балерина рухалася наче пір'їна."),
    ("a5f585a0-ba07-407c-9919-54e3d30d9dfe", "кидатися; робити раптовий рух уперед", "Він кинувся до дверей, щоб встигнути."),
    ("ca000026-0000-4000-8000-000000001026", "хитнутися; зробити раптовий нестійкий рух", "Автобус різко хитнувся на повороті."),
    ("06599763-fc0d-48b0-9e48-cffcddde508d", "розкішний; з багатим, солодким смаком або запахом", "Розкішна полуниця з вершками була справжньою насолодою."),
    ("6024d32a-4b8c-4344-b8d6-c23615abda77", "великодушний; щедрий і шляхетний, особливо до суперника", "Великодушний переможець не став принижувати програвшого."),
    ("f8c3ec01-3ae4-4629-9f0c-dfabbadf20cf", "злобний; що має намір завдати шкоди", "Злобний коментар у мережі образив тисячі людей."),
    ("b500002a-0000-4000-8000-00000000052a", "мандат; офіційне повноваження діяти", "Уряд отримав мандат від виборців на проведення реформ."),
    ("c700002a-0000-4000-8000-00000000072a", "маринувати; вимочувати продукт у приправленій рідині", "Потрібно маринувати м'ясо щонайменше кілька годин."),
    ("d605ff36-a3f9-497f-99ac-8e5323c7982e", "матріарх; жінка, яка очолює сімʼю або групу", "Стара матріарх тримала всю родину разом."),
    ("ce6c7bb3-e9b0-4602-9779-7fd21647256d", "максима; коротке правило поведінки або мудрості", "«Роби іншим те, що бажаєш собі» — відома максима."),
    ("ca000016-0000-4000-8000-000000001016", "зайвий; схильний втручатися в чужі справи", "Зайвий сусід постійно коментував усі рішення родини."),
    ("4113dc0c-8e66-4267-aa45-527a811cd8e8", "посередник; людина, яка допомагає вирішити спір", "Досвідчений посередник допоміг сторонам досягти згоди."),
    ("c700000e-0000-4000-8000-00000000070e", "педантичний; надзвичайно уважний до деталей", "Педантичний реставратор відновлював картину місяцями."),
    ("b5000004-0000-4000-8000-000000000504", "проміжне ПЗ; програмне забезпечення між різними застосунками", "Проміжне ПЗ забезпечує взаємодію між системами."),
    ("eb7c03d6-ae26-4909-a9aa-07471754d7e9", "віха; важливий етап або подія в розвитку", "Запуск першого продукту став важливою віхою для стартапу."),
    ("9ec010e4-fa11-45d4-b7f5-99f3b0559a44", "середовище; соціальне або культурне оточення людини", "Вона виросла в артистичному середовищі."),
    ("5b5a4812-f963-4084-af55-8661fd4ba3bf", "приниження; сильне відчуття сорому або ганьби", "Публічне приниження стало для нього болісним уроком."),
    ("b500001c-0000-4000-8000-00000000051c", "мотив; повторювальний елемент або тема в мистецтві", "Квітковий мотив пронизував усю колекцію."),
    ("cb000024-0000-4000-8000-000000001124", "бурмотіти; говорити тихо і нечітко", "Він щось бурмотів під ніс, не підіймаючи очей."),
    ("0599ac41-6cac-49e0-b618-48526c97c0db", "безліч; незліченна або дуже велика кількість", "У лісі чулася безліч птахів."),
    ("cb00002d-0000-4000-8000-00000000112d", "гризти; їсти маленькими шматочками", "Вона гризла печиво, читаючи книгу."),
    ("ca000028-0000-4000-8000-000000001028", "спритний; швидкий і легкий у рухах або думках", "Спритний карманник непомітно зник у натовпі."),
    ("ca000015-0000-4000-8000-000000001015", "безтурботний; показово спокійний і байдужий", "Він безтурботно знизав плечима у відповідь на критику."),
    ("ca00001c-0000-4000-8000-00000000101c", "новачок; людина, нова й недосвідчена в діяльності", "Як новачок, вона ставила безліч запитань."),
    ("218017f1-ab5a-40ce-b22e-cea7674ab809", "нюанс; тонка відмінність у значенні або вираженні", "Він розумів усі нюанси дипломатії."),
    ("85d6db1c-6eee-4a58-947a-14a437303320", "горіховий; що має смак горіхів або містить їх", "Горіховий аромат наповнив усю кухню."),
    ("ca00000a-0000-4000-8000-00000000100a", "одержимість; стійка ідея, що домінує в думках", "Його одержимість порядком дратувала сусідів по кімнаті."),
    ("b5000016-0000-4000-8000-000000000516", "коливання; повторний рух туди-сюди навколо центру", "Коливання маятника є рівномірними."),
    ("b5000011-0000-4000-8000-000000000511", "осмос; рух розчинника через мембрану; поступове засвоєння", "Мову можна вивчити через осмос — занурюючись у середовище."),
    ("1fa1f614-b994-4002-9bc6-08cf5cf81a94", "піднебіння; дах рота; здатність цінувати смаки", "Вишукане піднебіння сомельє одразу розпізнало якісне вино."),
    ("208bfa3f-d6e1-4a20-9f1e-f9d38cb0e964", "шарм; демонстративна впевненість у стилі", "Вона виступила з неабияким шармом."),
    ("7228f5bc-f6bd-4965-a15b-85ce7435521c", "панорама; широкий і безперервний вид на місцевість", "З вершини гори відкривалася приголомшлива панорама."),
    ("cb00000b-0000-4000-8000-00000000110b", "парадигма; зразковий приклад або модель мислення", "Революційне відкриття змінило наукову парадигму."),
    ("b5000020-0000-4000-8000-000000000520", "парадокс; твердження, що здається суперечливим, але може бути правдою", "Парадокс Зенона збентежував філософів тисячоліттями."),
    ("cb00001f-0000-4000-8000-00000000111f", "переказувати; виражати зміст іншими словами", "Перекажіть текст своїми словами."),
    ("b5000021-0000-4000-8000-000000000521", "пафос; якість, що викликає жаль або смуток", "Фільм був сповнений пафосу і сентиментальності."),
    ("c700001a-0000-4000-8000-00000000071a", "покровитель; людина, яка підтримує художника або заклад", "Меценат фінансував молодих митців."),
    ("b500000b-0000-4000-8000-00000000050b", "корисне навантаження; дані у передачі без заголовків", "Сервер отримав корисне навантаження запиту."),
    ("12dfd0bb-36ca-4b80-b385-1f4cfc87513f", "задумливий; занурений у глибокі, часто сумні думки", "Вона сиділа задумлива, дивлячись у вікно."),
    ("c747699f-77bd-4d78-9f00-8c17e351d760", "гострий; з сильним смаком перцю", "Гострий соус не всім припав до смаку."),
    ("489660c7-e667-4d93-9549-1533b71f496b", "сприйняття; спосіб розуміння або тлумачення чогось", "Її сприйняття ситуації суттєво відрізнялося від реальності."),
    ("c7000030-0000-4000-8000-000000000730", "просочуватися; проникати і поширюватися скрізь", "Запах кави просочився через увесь будинок."),
    ("cb00000d-0000-4000-8000-00000000110d", "персонаж; аспект чийогось характеру, представлений іншим", "Публічна персона актора не збігалася з реальною людиною."),
    ("cb000027-0000-4000-8000-000000001127", "пітніти; виділяти піт", "На спеці він одразу починав пітніти."),
    ("cb000012-0000-4000-8000-000000001112", "дріб'язковий; стурбований дрібницями", "Дріб'язкові суперечки псували атмосферу в колективі."),
    ("997edd54-98f1-4f23-984d-ca5736caf9b8", "примхливий; по-дитячому сварливий через дрібниці", "Примхлива дитина топала ногами у крамниці."),
    ("d69ecc79-9022-4a61-8245-12d66ffd5434", "заспокоювати; зменшувати чийсь гнів поступками", "Директор намагався заспокоїти незадоволених клієнтів."),
    ("ca000006-0000-4000-8000-000000001006", "спокійний; тихий і безтурботний", "Спокійне озеро відображало синє небо."),
    ("992d2688-4863-4a6f-a07b-c8c3c2aa1395", "надмір; велика або надмірна кількість чогось", "На ринку пропонувався надмір різних товарів."),
    ("baedeaf8-f286-4dca-b02b-4dc6daee052b", "стрімко падати; різко і швидко падати вниз", "Ціни на акції стрімко впали після новин."),
    ("0aa33536-eef9-4d80-87d6-59424d24099b", "врівноваженість; витончена і гідна поведінка", "Вона відповідала на незручні запитання з неймовірною врівноваженістю."),
    ("1f833f85-b732-413f-8da2-6cf443fcb898", "пихатий; що вдає з себе важливу або серйозну людину", "Пихата промова наганяла нудьгу."),
    ("b500002b-0000-4000-8000-00000000052b", "популізм; політичний підхід, що апелює до простих людей", "Популізм набирав силу під час економічної кризи."),
    ("47f8d3f5-34c4-4970-ad3f-9d1fb3fe8010", "поважний; дещо гладкий, але статечний", "Поважний джентльмен у капелюсі йшов парком."),
    ("2c5ac05f-d002-4236-91ea-ea6589bd2cb4", "прагматичний; той, хто вирішує проблеми практично", "Прагматичний підхід дав кращі результати."),
    ("7184b98f-9acb-4a23-af23-40557a03ed34", "схильність; тенденція до певної поведінки", "У неї була природна схильність до музики."),
    ("ca000009-0000-4000-8000-000000001009", "передчуття; сильне відчуття майбутньої події", "Якесь смутне передчуття не давало їй спати."),
    ("cb000030-0000-4000-8000-000000001130", "перемагати; виявлятися сильнішим або поширеним", "Зрештою здоровий глузд переміг."),
    ("b0f69b2b-6657-4e9f-a1c6-1ed53f3239c5", "проголошувати; офіційно або публічно оголошувати", "Мер проголосив місто побратимом іноземного міста."),
    ("ad39c681-ddf3-4f44-9952-edfa038f0bb5", "зволікання; звичка відкладати справи", "Зволікання до останнього моменту стало його головною проблемою."),
    ("9af4685f-7fb2-487b-b458-17c517f63540", "вундеркінд; молода людина з виключними талантами", "Маленький вундеркінд уже давав концерти у шість років."),
    ("f227c8d1-abd7-4162-af6c-64055d5fd53b", "нащадки; діти або потомство колективно", "Він залишив велику спадщину своїм нащадкам."),
    ("b5000025-0000-4000-8000-000000000525", "пролог; вступний розділ літературного твору", "Пролог роману одразу захопив читача."),
    ("0999519b-bff2-4273-b032-c9e2ba0afce8", "підопічний; той, кого підтримує досвідченіша людина", "Молодий підопічний режисера зняв свій перший фільм."),
    ("1ec862a2-1994-4828-bcec-483ceddc7e5f", "довірена особа; той, хто діє від імені іншого", "Він проголосував через довірену особу."),
    ("cb000015-0000-4000-8000-000000001115", "розсудливий; обережний і передбачливий", "Розсудливий інвестор не ризикував усіма заощадженнями."),
    ("15fe76c8-8adc-4cff-b928-b45c81977be3", "пуристський; надмірно стурбований пристойністю", "Пуристська реакція на фільм здивувала режисера."),
    ("7620023a-7768-4869-99b7-80f9d7aa779d", "задиркуватий; схильний до суперечок і бійок", "Задиркуватий характер заважав йому в колективі."),
    ("ca000029-0000-4000-8000-000000001029", "різкий; з гострим і сильним запахом або смаком", "Різкий запах цибулі заповнив кухню."),
    ("ac3c4f97-958a-4253-9fc3-6cd8b3883fb5", "докір сумлінні; неспокій щодо своєї поведінки", "Вона відчувала докір сумлінні, відмовивши в допомозі."),
    ("e18bde8b-a3d9-4685-80ab-300bbf708982", "причіпатися; сперечатися через дрібниці", "Не варто причіпатися до незначних деталей."),
    ("fd001d9b-9049-4613-97aa-7d5306bf6616", "дотеп; дотепне й влучне зауваження", "Його дотеп викликав сміх у всьому залі."),
    ("ca000020-0000-4000-8000-000000001020", "теревенити; безладно говорити або писати", "Він теревенив про всяке, відійшовши від теми."),
    ("ca00002a-0000-4000-8000-00000000102a", "прогірклий; з неприємним запахом від старості", "Прогірке масло довелося викинути."),
    ("ca00000c-0000-4000-8000-00000000100c", "злоба; тривала гірка образа", "Стара злоба між сусідами не давала їм миру."),
    ("ca000007-0000-4000-8000-000000001007", "взаєморозуміння; близькі й гармонійні стосунки", "Між учителем і класом виникло справжнє взаєморозуміння."),
    ("12baddbe-c34c-4817-a239-962b1db31b6b", "захоплений; цілком поглинутий тим, що відбувається", "Вона слухала лекцію з захопленою увагою."),
    ("cb000009-0000-4000-8000-000000001109", "раціоналізувати; виправдовувати поведінку логічними поясненнями", "Він намагався раціоналізувати своє запізнення."),
    ("c7000024-0000-4000-8000-000000000724", "підтверджувати; знову рішуче висловлювати підтримку", "Вона підтвердила свою відданість команді."),
    ("c700001e-0000-4000-8000-00000000071e", "докір; висловлення різкого невдоволення", "Він отримав публічний докір за своє недбальство."),
    ("ca00001e-0000-4000-8000-00000000101e", "спростовувати; доводити, що твердження хибне", "Адвокат спростував свідчення обвинувачення."),
    ("da4a90c6-456d-42c6-8647-f861bc070748", "заперечення; аргумент, що спростовує іншу позицію", "Її заперечення поклало край суперечці."),
    ("00106781-a1a0-45e5-a54b-0b7eb2141fcc", "відлюдник; людина, яка уникає товариства", "Старий відлюдник жив на краю села сам-один."),
    ("c7000027-0000-4000-8000-000000000727", "відсахнутися; раптово відступити від страху або огиди", "Вона відсахнулась, побачивши павука."),
    ("b5000008-0000-4000-8000-000000000508", "рекурсія; процес, у якому функція викликає саму себе", "Рекурсія є потужним інструментом у програмуванні."),
    ("361a99ab-3fe4-46ad-97f5-3fbdb87bf33a", "ароматний; що сильно пахне чимось", "Ліс був ароматний свіжою хвоєю після дощу."),
    ("b5000002-0000-4000-8000-000000000502", "надмірність; дублювання компонентів для резервування", "Надмірність системи запобігала збоям."),
    ("b5000030-0000-4000-8000-000000000530", "референдум; пряме голосування з одного питання", "Уряд оголосив референдум щодо вступу до союзу."),
    ("b5000012-0000-4000-8000-000000000512", "рефракція; викривлення світла між середовищами", "Рефракція спричиняє викривлення предметів у воді."),
    ("97ba5386-20e3-4bc5-b377-77dc52541339", "спростовувати; доводити хибність твердження або людини", "Вченому вдалося спростувати популярний міф."),
    ("ca00001d-0000-4000-8000-00000000101d", "повторювати; говорити знову для підкреслення", "Він ще раз повторив головні тези виступу."),
    ("37c1fdda-fa19-4a43-9c95-c8bb80cf6a70", "відповідь; гостра або дотепна репліка", "Її влучна відповідь поставила суперника в глухий кут."),
    ("c7000031-0000-4000-8000-000000000731", "відмовлятися; добровільно відмовлятися від права чи претензії", "Він відмовився від посади заради сімʼї."),
    ("c7000004-0000-4000-8000-000000000704", "каяття; глибокий жаль або провина за скоєне", "Глибоке каяття не давало йому спокою."),
    ("6d7acb6e-63f9-4f3b-9b6b-516beac06a8e", "перепалка; жвава розмова з дотепними репліками", "Їхня перепалка розсмішила всіх присутніх."),
    ("1a6c3e5e-64de-43a0-a43a-fe05796821b7", "репресія; несвідоме блокування неприємних думок", "Психолог досліджував механізми репресії у пацієнтів."),
    ("c5440872-c15b-4615-aa3d-51683dae3a41", "догана; офіційне і суворе осудження", "Директор оголосив догану за запізнення."),
    ("58080528-b96c-4ef6-8cfa-b0fb97dfe27c", "докір; висловлення незадоволення або розчарування", "Її погляд був повний мовчазного докору."),
    ("96e19b6a-c998-41cc-811e-8be47a1839bf", "стійкість; здатність швидко відновлюватися після труднощів", "Стійкість народу перед обличчям випробувань вражала."),
    ("ca00000b-0000-4000-8000-00000000100b", "рішучість; тверда рішучість щось зробити", "Вона діяла з незламною рішучістю."),
    ("9512ffdb-6fb5-42e5-bcc4-778af6253e2c", "стриманий; неохоче розмовляє; замкнений", "Стриманий свідок відповідав коротко і неохоче."),
    ("2c6d2850-c833-4079-95ff-b9fb669d20e1", "відповідати різко; давати гостру дотепну відповідь", "Він відповів різко, не роздумуючи."),
    ("f84a4107-466f-4e61-beb0-d6d143d8e5e0", "контрудар; швидка і дотепна відповідь на критику", "Її блискуча відповідь завершила дискусію."),
    ("ca000027-0000-4000-8000-000000001027", "міцний; сильний і здоровий; здатний витримати труднощі", "Міцна конструкція витримала штормові навантаження."),
    ("d74770b4-a2f2-480b-898e-f2b3a33809fa", "розмірковувати; глибоко і повторно думати над чимось", "Вона довго розмірковувала над пропозицією."),
    ("6064cbf3-240e-49c0-ae36-5bbe15eca2ed", "значущість; якість бути особливо помітним або виділятися", "Яскравий колір підвищував візуальну значущість знаку."),
    ("94343007-5a7e-42bd-8a5d-cbd703048740", "блідий; нездорового жовтуватого або землистого кольору", "Блідий вигляд свідчив про втому і нестачу сну."),
    ("90c1f11d-0958-448b-886f-e31aac6eebd1", "лицемірно-побожний; що виставляє себе морально вищим", "Лицемірно-побожні коментарі дратували всіх."),
    ("67aa985b-a4ac-437e-b9a2-89afc8eb4326", "оптимістичний; впевнений і оптимістичний у складній ситуації", "Він залишався оптимістичним навіть за несприятливих обставин."),
    ("d7d0782a-dc0e-46b7-a27b-8d0818673b5d", "саркастичний; глузливо-цинічний у виразі", "Його саркастична усмішка говорила більше слів."),
    ("b5000001-0000-4000-8000-000000000501", "масштабованість; здатність системи обробляти зростаючі навантаження", "Масштабованість платформи дозволила обслуговувати мільйони користувачів."),
    ("cf43b107-3237-4ad8-88ac-ddae418bb05f", "тюпати; бігти швидко і легко, часто грайливо", "Мишка тюпала по підлозі, шукаючи їжу."),
    ("095f4ef2-9b2d-49cd-b310-9b0720ab6518", "козел відпущення; той, кого звинувачують у чужих провинах", "Його зробили козлом відпущення в цьому скандалі."),
    ("ca00002e-0000-4000-8000-00000000102e", "рідкісний; недостатній для задоволення попиту", "Чиста вода була рідкісною в посушливому регіоні."),
    ("ce4afa53-f246-4b07-a154-220e2e5172fc", "нащадок; молодий представник знатної родини", "Він є нащадком давнього козацького роду."),
    ("f1443c7b-d630-4313-a5a7-026deba5b731", "тощий; неприємно тонкий і кістлявий", "Тощий кіт скиглив під дверима."),
    ("c7000015-0000-4000-8000-000000000715", "сумлінний; ретельний і уважний до правил", "Сумлінний аудитор перевірив кожну цифру."),
    ("b5000019-0000-4000-8000-000000000519", "осад; речовина, що осідає на дно рідини", "На дні пляшки утворився виноградний осад."),
    ("658e2990-ee53-479c-995b-f9cb4bc910cb", "почуття; думка або ставлення, засноване на емоції", "Громадське почуття щодо цього питання змінилося."),
    ("ca00000d-0000-4000-8000-00000000100d", "проникливий; той, хто має гострий практичний розум", "Проникливий підприємець відразу побачив можливість."),
    ("cb00002a-0000-4000-8000-00000000112a", "нудитися; варитися на повільному вогні або бути на межі вибуху", "Суп повинен нудитися принаймні годину."),
    ("cb000026-0000-4000-8000-000000001126", "горбитися; стояти, сидіти або ходити зігнувшись", "Не горбся, тримай спину прямо."),
    ("c7000028-0000-4000-8000-000000000728", "дрімати; спати легким або спокійним сном", "Дитина спокійно дрімала в кріслі."),
    ("ca000002-0000-4000-8000-000000001002", "самовдоволений; що виявляє дратівливе самовдоволення", "Самовдоволена посмішка переможця роздратувала суперника."),
    ("b5000027-0000-4000-8000-000000000527", "суверенітет; вища влада або незалежність держави", "Суверенітет країни охороняється конституцією."),
    ("8b97bfe8-1654-40cf-b794-19424ed274d8", "видовище; вражаючий захід або дійство", "Карнавал став справжнім видовищем для гостей міста."),
    ("ca000019-0000-4000-8000-000000001019", "глядач; людина, яка спостерігає за подією", "Тисячі глядачів зібралися на стадіоні."),
    ("ed7758db-19b0-41a0-bad4-93c9c0a941f5", "тонкий і довгий; довгий і тонкий, на вигляд слабкий", "Тонкі і довгі ноги жирафа миттєво впізнавані."),
    ("cb00001a-0000-4000-8000-00000000111a", "речник; людина, яка виступає від імені групи", "Речник уряду прокоментував ситуацію."),
    ("3324030e-feb2-406d-8422-3fbbebf6fe87", "вразливий; той, кого легко нудить або жахає", "Вразливий студент не зміг дивитися на операцію."),
    ("cb000023-0000-4000-8000-000000001123", "заїкатися; говорити з мимовільними паузами", "Від хвилювання він почав заїкатися."),
    ("ca00001f-0000-4000-8000-00000000101f", "обумовлювати; вимагати як умову угоди", "Контракт обумовлював доставку впродовж семи днів."),
