def main():
    conn = sqlite3.connect(DB)
    inserted = skipped = 0
    with conn:
        for word_id, definition, example in TRANSLATIONS:
            row = conn.execute("SELECT id FROM words WHERE id = ?", (word_id,)).fetchone()
            if not row:
                print(f"  SKIP (not found): {word_id}")
                skipped += 1
                continue
            conn.execute("""
                INSERT OR REPLACE INTO translations (word_id, lang, definition, example)
                VALUES (?, 'uk', ?, ?)
            """, (word_id, definition, example))
            inserted += 1
    print(f"Done: {inserted} inserted, {skipped} skipped — intermediate uk")
    conn.close()

if __name__ == "__main__":
    main()
